function seed(n){ return n === "mature" ? { tutorial: 9, scrap: 10, credits: 82, storeUnits: 900, capacity: 900, data: 102, drone: true, pulses: 6, overflow: 0, power: "0 of 8 units requested", busy: "97% busy (3/24 in transit)", waiting: 8, rows: STORE_M, machines: MACH.map(function(m){ return Object.assign({}, m); }), known: [0,1,2], tick: 450330, links: 18 } : { tutorial: 0, scrap: 0, credits: 0, storeUnits: 0, capacity: 900, data: 0, drone: false, pulses: 0, overflow: 0, power: "0 of 8 units requested", busy: "0% busy (0/24 in transit)", waiting: 0, rows: [], machines: [], known: [], tick: 0, links: 0 }; }
function boot(n){ S.data = seed(n); S.dest = "yard"; S.stack = []; S.machine = null; S.sub = 0; S.blueprint = null; S.ghost = 8; S.pressed = 0; S.log = []; S.toast = null; S.importText = ""; S.importError = null; S.started = n === "gate" ? false : true; S.settings = { muted: false, textScale: 1, reducedMotion: false }; S.unlocked = { sorter: true }; render(); }
var QD = String.fromCharCode(34), QA = String.fromCharCode(39);
function el(id){ return document.getElementById(id); }
function btn(id, v, c, kind, dis, fn){ HAND[id] = fn || null; var cls = "f" + (kind === "p" ? " f--p" : "") + (kind === "on" ? " f--on" : ""); var o = ""; o += "<button class=" + QD + cls + QD; o += " id=" + QD + id + QD; o += " onclick=" + QA + "RW47.tap(" + QD + id + QD + ")" + QA; o += dis ? " disabled" : ""; o += ">" + "<span>" + v + "</span>"; if (c) { o += "<span class=" + QA + "c" + QA + ">" + c + "</span>"; } o += "</button>"; return o; }
function lock(id, v, why){ HAND[id] = null; var o = "<div class=" + QD + "f" + QD + " id=" + QD + id + QD + " aria-disabled=" + QD + "true" + QD + ">"; o += "<span>" + v + "</span><span class=" + QA + "lk" + QA + ">" + why + "</span></div>"; return o; }
function rows(pairs){ var h = "<div class=" + QA + "rows" + QA + ">"; for (var i = 0; i < pairs.length; i++) { h += "<i>" + pairs[i][0] + "</i><b>" + pairs[i][1] + "</b>"; } return h + "</div>"; }
function bar(v, max){ var p = Math.max(0, Math.min(100, Math.round((v / max) * 100))); return "<span class=" + QA + "fill" + QA + "><i style=" + QA + "width:" + p + "%" + QA + "></i></span>"; }
function tap(id){ S.pressed++; var n = el(id); S.log.push({ n: S.pressed, id: id, label: n ? (n.textContent || "").trim() : id }); var h = HAND[id]; if (h) h(); render(); }
function key(k){ S.pressed++; S.log.push({ n: S.pressed, id: "key-" + k, label: k }); if (k === "Escape") { pop(); } render(); }
function tapCanvas(x, y){ S.pressed++; S.log.push({ n: S.pressed, id: "canvas", label: "world tap" }); if (S.blueprint !== null) { S.ghost = 8; place(); return; } var hit = pick(x, y); S.machine = hit; render(); }
function pick(x, y){ var box = el("world").getBoundingClientRect(); for (var i = 0; i < S.data.machines.length; i++) { var p = tilePt(S.data.machines[i].tile, box); if (Math.abs(p.x - x) < 26 && Math.abs(p.y - y) < 22) { return S.data.machines[i].id; } } return null; }
function tilePt(tile, box){ var cols = 4, s = Math.min(box.width / 5, box.height / 7); var cx = box.width / 2, cy = box.height / 2 + s; var col = tile % cols, row = Math.floor(tile / cols); return { x: cx + (col - row) * s * 0.95, y: cy + (col + row) * s * 0.55 - s * 1.6 }; }
function flash(t){ S.toast = t; }
function push(id){ S.stack.push({ id: id, ret: document.activeElement && document.activeElement.id ? document.activeElement.id : null }); S.hist = (S.hist || 0) + 1; try { history.pushState({ d: S.stack.length }, ""); } catch (e) { S.hist = S.stack.length; } }
function pop(fromHistory){ var top = S.stack.pop(); if (top) { if (top.id.indexOf("dest:") === 0) { S.dest = "yard"; } else if (top.id.indexOf("ent:") === 0) { S.machine = null; } else if (top.id.indexOf("sub:") === 0) { S.sub = 0; } else if (top.id.indexOf("page:") === 0) { S.importPage = false; } if (top.ret && el(top.ret)) { try { el(top.ret).focus(); } catch (e) { } } } if (!fromHistory && S.hist > 0) { S.hist -= 1; try { history.back(); } catch (e) { } } render(); }
function go(dest){ if (S.dest === dest) { return; } if (dest === "yard") { S.dest = "yard"; S.machine = null; S.sub = 0; S.stack.length = 0; S.hist = 0; } else { S.dest = dest; S.machine = null; S.sub = 0; push("dest:" + dest); } render(); }
function openMachine(id){ S.machine = id; S.sub = 0; if (S.dest === "yard") { push("ent:machine-" + id); } render(); }
function openSub(n){ S.sub = n; push("sub:" + n); render(); }
function salvage(){ var d = S.data; d.scrap += 5; d.storeUnits += 5; d.pulses += 1; if (d.pulses >= 6 && d.tutorial <= 1) { d.tutorial = 2; } flash("Cutting pulse recharging"); }
function repair(){ var d = S.data; if (d.scrap < 30) { flash("Need 30 scrap " + U.mid + " have " + d.scrap); return; } d.scrap -= 30; d.drone = true; d.tutorial = 3; }
function bpName(b){ return b === "furnace" ? "Furnace" : "Scrap sorter"; }
function bpCost(b){ return b === "furnace" ? "20 scrap " + U.mid + " 5 ferrous" : "20 scrap"; }
function place(){ var d = S.data; var cost = S.blueprint === "furnace" ? 25 : 20; if (d.scrap < cost) { flash("Need " + cost + " scrap " + U.mid + " have " + d.scrap); return; } d.scrap -= cost; d.storeUnits = Math.max(0, d.storeUnits - cost); d.machines.push({ id: d.machines.length + 1, n: bpName(S.blueprint), tile: S.ghost, lvl: 1, cyc: "4.00s", rate: "0.00", max: "0.25", pw: "1 unit", need: "2 Scrap", next: "Needs 2 scrap, which nothing in the yard", up: "4.00s \u2192 3.80s", price: 30 }); S.blueprint = null; S.machine = d.machines.length; if (d.tutorial <= 6) { d.tutorial = 4; } }
function sell(res){ var q = SELL_M[res][0], cr = SELL_M[res][1]; var d = S.data; var row = null; for (var i = 0; i < d.rows.length; i++) { if (d.rows[i][0] === res) { row = d.rows[i]; } } if (!row || row[1] < q) { flash("Need " + q + " units " + U.mid + " have " + (row ? row[1] : 0)); return; } row[1] -= q; d.storeUnits = Math.max(0, d.storeUnits - q); d.credits += cr; flash("Sold " + q + " " + res + " " + U.mid + " +" + cr + " credits"); }
function upgrade(branch, price){ var d = S.data; if (d.credits < price) { flash("Need " + price + " credits " + U.mid + " have " + d.credits); return; } d.credits -= price; for (var i = 0; i < d.machines.length; i++) { if (d.machines[i].id === S.machine) { d.machines[i].lvl += 1; d.machines[i].chosen = branch; } } flash("Upgraded " + branch); }
function buyNode(i){ var d = S.data; var cost = NODES[i][2]; if (d.data < cost) { flash("Need " + cost + " Data " + U.mid + " have " + d.data); return; } d.data -= cost; if (d.known.indexOf(i) < 0) { d.known.push(i); } }
function chipMax(){ var w = window.innerWidth; return w < 380 ? 3 : (w < 600 ? 4 : 7); }
function chipList(){ var d = S.data; var out = []; var have = function(n){ for (var i = 0; i < d.rows.length; i++) { if (d.rows[i][0] === n) { return d.rows[i][1]; } } return 0; }; out.push(["Scrap", d.scrap]); if (have("Ferrous")) { out.push(["Ferrous", have("Ferrous")]); } out.push(["Credits", d.credits]); out.push(["Store", d.storeUnits + "/" + d.capacity]); ["Nonferrous", "Wire", "Plates", "Circuits", "Data"].forEach(function(n){ if (have(n)) { out.push([n, have(n)]); } }); return out.slice(0, chipMax()); }
function renderBand(){ var h = "<div class=" + QA + "chips" + QA + ">"; var cs = chipList(); for (var i = 0; i < cs.length; i++) { h += "<span class=" + QA + "chip" + QA + ">" + cs[i][0] + " <b>" + cs[i][1] + "</b></span>"; } h += "</div>"; h += "<div class=" + QA + "cluster" + QA + ">"; var big = S.settings.textScale >= 1.5; h += btn("tgl-sound", S.settings.muted ? (big ? "\u2717" : "Sound ?") : (big ? "\u2713" : "Sound \u2713"), null, null, false, function(){ S.settings.muted = !S.settings.muted; }); h += btn("tgl-scale", "A " + S.settings.textScale, null, null, false, function(){ var steps = [1, 1.25, 1.5, 2]; S.settings.textScale = steps[(steps.indexOf(S.settings.textScale) + 1) % steps.length]; document.documentElement.style.setProperty("--ts", String(S.settings.textScale)); }); h += btn("tgl-motion", "MOTION", S.settings.reducedMotion ? "on" : "off", S.settings.reducedMotion ? "on" : null, false, function(){ S.settings.reducedMotion = !S.settings.reducedMotion; }); h += "</div>"; el("band").innerHTML = h; }
function renderCard(){ if (!S.started) { el("card").innerHTML = ""; return; } var d = S.data; var p = primarySpec(); var h = "<span class=" + QA + "p" + QA + ">Next: " + p.v + "</span>"; if (window.innerHeight >= 460) { var n = "Drones " + (d.drone ? 5 : 0) + " " + U.mid + " Power 8 " + U.mid + " " + d.power + " " + U.mid + " 100 %"; if (S.blueprint !== null) { n += " " + U.mid + " waits " + (S.blueprint === "furnace" ? 25 : 20) + " scrap " + U.mid + " have " + d.scrap; } h += "<span class=" + QA + "s" + QA + ">" + n + "</span>"; } el("card").innerHTML = h; }
function renderNav(){ if (!S.started) { el("nav").innerHTML = ""; return; } var h = ""; var spec = primarySpec(); var slots = [["yard", "Yard"], ["build", "Build"], ["store", "Store"], ["research", "Research"], ["menu", "Menu"]]; for (var i = 0; i < slots.length; i++) { var k = slots[i][0], label = slots[i][1]; var idn = "nav-" + k; if (k === "research" && S.data.data < 1 && S.data.known.length === 0) { h += lock(idn, label, "Needs 1 Data"); continue; } h += btn(idn, label, null, S.dest === k ? "on" : null, false, (function(key){ return function(){ go(key); }; })(k)); } el("nav").innerHTML = h; }
function forkShown(){ var d = S.data; return S.machine !== null && S.dest === "yard" && S.sub === 0 && d.credits >= 0 && d.machines.length > 0; }
function machineOf(){ for (var i = 0; i < S.data.machines.length; i++) { if (S.data.machines[i].id === S.machine) { return S.data.machines[i]; } } return null; }
function renderAction(){ var h = ""; if (!S.started) { h += btn("gate-begin", "Begin recovery", null, "p", false, function(){ S.started = true; }); h += btn("tgl-sound-g", "Sound \u2713", null, null, false, function(){ S.settings.muted = !S.settings.muted; }); el("action").innerHTML = h; return; } if (S.blueprint !== null) { h += btn("build-cancel", "Cancel", null, null, false, function(){ S.blueprint = null; }); h += btn("action-primary", "Place " + bpName(S.blueprint), bpCost(S.blueprint), "p", S.data.scrap < (S.blueprint === "furnace" ? 25 : 20), place); h += btn("build-next", "Next", null, null, false, function(){ S.blueprint = S.blueprint === "sorter" ? "furnace" : "sorter"; }); el("action").innerHTML = h; return; } if (forkShown()) { var m = machineOf(); var p1 = m.price || 222, p2 = (m.price || 222) + 10; h += btn("fork-draw", "Upgrade Less power", p1 + " credits", "p", S.data.credits < p1, function(){ upgrade("Less power", p1); }); h += btn("fork-speed", "Upgrade Faster batches", p2 + " credits", null, S.data.credits < p2, function(){ upgrade("Faster batches", p2); }); el("action").innerHTML = h; return; } var p = primarySpec(); h += btn("action-primary", p.v, p.c, "p", !!p.dis, p.fn); el("action").innerHTML = h; }
function primarySpec(){ var d = S.data; if (d.rows.length) { var s = SELL_M.Ferrous; return { v: "Sell Ferrous", c: s[0] + " units " + U.mid + " +" + s[1] + " credits", dis: false, fn: function(){ sell("Ferrous"); } }; } if (d.tutorial <= 1) { return { v: "Salvage", c: null, dis: false, fn: salvage }; } if (d.tutorial === 2) { return { v: "Repair drone", c: "30 scrap", dis: d.scrap < 30, fn: repair }; } if (d.machines.length === 0) { return { v: "Build Scrap sorter", c: "20 scrap", dis: d.scrap < 20, fn: function(){ S.blueprint = "sorter"; S.ghost = 8; place(); } }; } if (d.links === 0) { return { v: "Connect sorter to the dock", c: null, dis: false, fn: function(){ S.data.links = 2; } }; } return { v: "Add drone", c: "45 credits", dis: d.credits < 45, fn: function(){ S.data.credits += 0; } }; }
function diamond(g, x, y, c){ g.strokeStyle = c; g.lineWidth = 1; g.beginPath(); g.moveTo(x, y - 10); g.lineTo(x + 18, y); g.lineTo(x, y + 10); g.lineTo(x - 18, y); g.closePath(); g.stroke(); }
function renderWorld(){ var cv = el("cv"); var box = el("world").getBoundingClientRect(); if (!box.width) { return; } var dpr = Math.min(2, Math.max(1, window.devicePixelRatio || 1)); cv.width = Math.round(box.width * dpr); cv.height = Math.round(box.height * dpr); var g = cv.getContext("2d"); g.setTransform(dpr, 0, 0, dpr, 0, 0); g.fillStyle = "#0e1726"; g.fillRect(0, 0, box.width, box.height); var t; for (t = 0; t < 12; t++) { var p = tilePt(t, box); diamond(g, p.x, p.y, "#22384a"); } for (t = 0; t < S.data.machines.length; t++) { var m = S.data.machines[t]; var q = tilePt(m.tile, box); g.fillStyle = (m.rate === "0.00") ? "#c9713a" : "#5fd8e8"; g.fillRect(q.x - 14, q.y - 12, 28, 24); g.fillStyle = "#0b1220"; g.font = "10px ui-monospace,Consolas,monospace"; g.fillText(String(m.id), q.x - 3, q.y + 3); } if (S.blueprint !== null) { var r = tilePt(S.ghost, box); g.strokeStyle = "#ffb765"; g.lineWidth = 2; g.strokeRect(r.x - 16, r.y - 14, 32, 28); } if (!S.data.machines.length) { var wq = tilePt(2, box); g.strokeStyle = "#8a7ad8"; g.lineWidth = 2; g.beginPath(); g.arc(wq.x, wq.y, 12, 0, 6.283); g.stroke(); } }
function renderToast(){ var t = el("toast"); if (!t) { return; } if (S.toast) { t.hidden = false; t.textContent = S.toast; } else { t.hidden = true; t.textContent = ""; } }
function render(){ renderBand(); renderCard(); renderNav(); renderAction(); renderInsp(); renderWorld(); renderToast(); }
